    "title": "你手机里，有最舍不得删的一张照片吗？\\n\\n前不久，我们在社交网络上看到一个帖子，一位丈夫写，他的妻子在生产时疑似羊水栓塞，情况凶险，经过艰难抢救活了下来。当时，妻子在ICU醒来，在纸上写了两句话，第一句是「宝宝还好？」第二句问，丈夫是否在外面？\\n\\n人生的牵挂凝结在那张纸上，丈夫保存了这张纸条的照片，舍不得删。\\n\\n有人说，人一生其实只活几个瞬间。而照片会把珍贵的瞬间凝聚成永恒。\\n\\n我们舍不得删的照片，大概是多种多样的吧？关于生离，关于死别，也关于生命中值得纪念的日子，不能忘却的人……它那么重要",
